import sys

def fibonacci(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b

def find_arithmetic_sequence(n, a, d):
    for b in range(1, 2**64):
        for e in range(1, 2**64):
            valid = True
            for i in range(n):
                fib = fibonacci(b + i * e)
                fib_str = str(fib)
                if len(fib_str) < 18:
                    fib_str = '0' * (18 - len(fib_str)) + fib_str
                if str(a + i * d) not in fib_str[-18:]:
                    valid = False
                    break
            if valid:
                return b, e
    return -1, -1

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    a = int(data[1])
    d = int(data[2])
    b, e = find_arithmetic_sequence(n, a, d)
    if b == -1:
        print(-1)
    else:
        print(b, e)

